package com.example.shortener.feature.link.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestTemplate; import java.util.Map;
@Service public class GeoService { private final String url; private final RestTemplate rest=new RestTemplate(); public GeoService(@Value("${app.geo-api-url}")String url){this.url=url;} public GeoInfo lookup(String ip){if(ip==null||ip.isBlank()||ip.equals("127.0.0.1")||ip.equals("0:0:0:0:0:0:0:1"))return new GeoInfo("Local","Local"); try{Map<?,?> r=rest.getForObject(url+"/"+ip+"/json/",Map.class);return new GeoInfo(r==null?null:(String)r.get("country_name"),r==null?null:(String)r.get("city"));}catch(Exception e){return new GeoInfo(null,null);}} public record GeoInfo(String country,String city){} }
